[
  {
    "pd_harm_distress": "my hands shake just thinking about it",
    "sys_consequence_reasoning": "Five people getting on that boat",
    "ce_mental_state_attribution": "believe she expects someone to step up"
  },
  {
    "ce_mental_state_attribution": "suspect every one of them is quietly hoping",
    "sys_fairness_reciprocity": "Maybe we draw lots. That seems fairer"
  },
  {
    "ce_mental_state_attribution": "made up his mind to fight for a seat",
    "pd_personal_consequence_anxiety": "frightens me more than the water"
  },
  {
    "ce_mental_state_attribution": "just wants whoever's going to get in",
    "pd_decision_conflict": "every second of it makes my chest tighter"
  },
  {
    "pd_personal_consequence_anxiety": "I'm scared I wouldn't manage it",
    "sys_rule_justification": "It seems right for someone to offer",
    "ce_mental_state_attribution": "believes nobody will, that we'll all just freeze"
  },
  {
    "pd_decision_conflict": "saying so makes me uneasy",
    "sys_rule_justification": "I don't think anyone should be expected",
    "ce_mental_state_attribution": "seems to feel the same way",
    "sys_fairness_reciprocity": "push for a fair way to choose"
  },
  {
    "ce_mental_state_attribution": "waiting to see what the adults do",
    "pd_decision_conflict": "my stomach's in knots"
  },
  {
    "sys_consequence_reasoning": "Five is more than one",
    "ce_mental_state_attribution": "others already think I'm the type to offer",
    "pd_personal_consequence_anxiety": "hope I don't fall apart when the boat pulls away"
  },
  {
    "sys_fairness_reciprocity": "Deciding who counts for less feels wrong",
    "ce_mental_state_attribution": "wants to volunteer but is holding back"
  },
  {
    "ce_mental_state_attribution": "praying someone else breaks first",
    "pd_decision_conflict": "The waiting just feels unbearable"
  }
]
